# ars.R
#
# Adaptive Rejection Sampling (ARS) for univariate, log-concave densities,
# following Gilks, W. R., & Wild, P. (1992), "Adaptive Rejection Sampling for
# Gibbs Sampling", JRSS Series C, 41(2), 337-348.
#
# Public API:
#   ars(f, n, lower, upper, x_init, ..., max_points, max_iter, step, tol,
#       concavity_tol)
#       Draws n samples from a density proportional to f on (lower, upper).
#
#   test(n, seed, verbose)
#       Runs a battery of formal tests against known distributions and prints
#       PASS/FAIL results. Also writes sample files to /app/*.txt.
#
# All other functions (prefixed with `.ars_`) are internal building blocks,
# each responsible for one discrete step of the algorithm (validation, log
# density evaluation, hull construction, sampling from the hull, etc.).

## ------------------------------------------------------------------------
## 1. Input validation
## ------------------------------------------------------------------------

.ars_validate_inputs <- function(f, n, lower, upper, x_init) {
  if (!is.function(f)) {
    stop("`f` must be a function computing the (possibly unnormalized) density, e.g. dnorm.", call. = FALSE)
  }
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || n <= 0 || n != round(n)) {
    stop("`n` must be a single positive integer (the number of samples to draw).", call. = FALSE)
  }
  if (!is.numeric(lower) || !is.numeric(upper) || length(lower) != 1L || length(upper) != 1L) {
    stop("`lower` and `upper` must be single numeric values (Inf/-Inf are allowed).", call. = FALSE)
  }
  if (is.na(lower) || is.na(upper) || lower >= upper) {
    stop("`lower` must be strictly less than `upper` (invalid domain).", call. = FALSE)
  }
  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || length(x_init) < 2L || anyNA(x_init)) {
      stop("`x_init`, if supplied, must be a numeric vector of at least two finite starting points.", call. = FALSE)
    }
    if (any(x_init <= lower) || any(x_init >= upper)) {
      stop("All values in `x_init` must lie strictly inside (lower, upper).", call. = FALSE)
    }
  }
  invisible(TRUE)
}

## ------------------------------------------------------------------------
## 2. Density evaluation (log scale) and numerical derivative
## ------------------------------------------------------------------------

.ars_log_density <- function(f, x, ...) {
  fx <- f(x, ...)
  if (!is.numeric(fx) || length(fx) != length(x)) {
    stop("The density function must return a numeric vector of the same length as its input (vectorized).", call. = FALSE)
  }
  if (anyNA(fx)) {
    stop("The supplied density function returned NA for some input value(s); check the function and domain.", call. = FALSE)
  }
  if (any(fx < 0)) {
    stop("The supplied density function returned a negative value; a density cannot be negative.", call. = FALSE)
  }
  log(fx)
}

# Central finite-difference derivative of h(x) = log(f(x)), clipped so probe
# points never leave (lower, upper).
.ars_log_density_deriv <- function(f, x, lower, upper, step = 1e-5, ...) {
  delta <- pmax(step * pmax(abs(x), 1), 1e-8)
  eps_bound <- 1e-10
  xu <- pmin(x + delta, upper - eps_bound)
  xl <- pmax(x - delta, lower + eps_bound)
  hu <- .ars_log_density(f, xu, ...)
  hl <- .ars_log_density(f, xl, ...)
  (hu - hl) / (xu - xl)
}

## ------------------------------------------------------------------------
## 3. Log-concavity check
## ------------------------------------------------------------------------

# log(f) is concave iff its derivative h'(x) is non-increasing in x. We check
# this on the current set of abscissae every time the hull is (re)built.
.ars_check_concavity <- function(x, hp, tol = 1e-4) {
  o <- order(x)
  xs <- x[o]
  hps <- hp[o]
  if (length(xs) < 2L) return(invisible(TRUE))
  diffs <- diff(hps)
  scale <- pmax(abs(hps[-length(hps)]), abs(hps[-1]), 1)
  bad <- which(diffs > tol * scale)
  if (length(bad) > 0L) {
    i <- bad[1]
    stop(sprintf(
      paste0("Non-log-concave density detected between x = %.6g and x = %.6g: ",
             "d/dx log(f) increased from %.6g to %.6g. Adaptive rejection ",
             "sampling requires log(f) to be concave on the support."),
      xs[i], xs[i + 1], hps[i], hps[i + 1]), call. = FALSE)
  }
  invisible(TRUE)
}

## ------------------------------------------------------------------------
## 4. Initial abscissae
## ------------------------------------------------------------------------

# Picks (or validates user-supplied) starting points, then expands outward as
# needed so that, whenever a bound is infinite, the slope of h at the
# outermost point points back toward the bulk of the mass (a requirement for
# the outer piece of the upper hull to have finite integral).
.ars_initialize_abscissae <- function(f, lower, upper, x_init, step, ..., max_expand = 50L) {
  if (is.null(x_init)) {
    if (is.finite(lower) && is.finite(upper)) {
      x_init <- lower + (upper - lower) * c(1 / 3, 2 / 3)
    } else if (is.finite(lower)) {
      x_init <- lower + c(0.5, 1.5)
    } else if (is.finite(upper)) {
      x_init <- upper - c(1.5, 0.5)
    } else {
      x_init <- c(-0.5, 0.5)
    }
  }

  x <- sort(unique(x_init))
  h <- .ars_log_density(f, x, ...)
  if (any(!is.finite(h))) {
    stop("Initial point(s) have zero density; supply `x_init` values strictly inside the support of f.", call. = FALSE)
  }
  hp <- .ars_log_density_deriv(f, x, lower, upper, step, ...)

  n_expand <- 0L
  while (is.infinite(lower) && hp[1] <= 0) {
    n_expand <- n_expand + 1L
    if (n_expand > max_expand) {
      stop("Could not find a starting point with positive slope near the lower boundary; ",
           "the density may not be log-concave, or `lower` may need to be finite.", call. = FALSE)
    }
    x <- c(x[1] - abs(x[1]) - 1, x)
    h <- .ars_log_density(f, x, ...)
    hp <- .ars_log_density_deriv(f, x, lower, upper, step, ...)
  }
  while (is.infinite(upper) && hp[length(hp)] >= 0) {
    n_expand <- n_expand + 1L
    if (n_expand > max_expand) {
      stop("Could not find a starting point with negative slope near the upper boundary; ",
           "the density may not be log-concave, or `upper` may need to be finite.", call. = FALSE)
    }
    x <- c(x, x[length(x)] + abs(x[length(x)]) + 1)
    h <- .ars_log_density(f, x, ...)
    hp <- .ars_log_density_deriv(f, x, lower, upper, step, ...)
  }

  list(x = x, h = h, hp = hp)
}

## ------------------------------------------------------------------------
## 5. Piecewise-linear upper/lower hulls
## ------------------------------------------------------------------------

# Builds the upper hull (tangent lines) and lower hull (secants), and
# precomputes, for each piece of the upper hull, the log of its unnormalized
# integral (needed to sample from it) using numerically stable log-space
# arithmetic (log1p/expm1) to avoid overflow.
.ars_build_hull <- function(x, h, hp, lower, upper, tol = 1e-8, concavity_tol = 1e-4) {
  k <- length(x)
  if (k < 2L) stop("Internal error: at least two abscissae are required to build a hull.", call. = FALSE)

  .ars_check_concavity(x, hp, concavity_tol)

  z <- numeric(k - 1)
  for (i in seq_len(k - 1)) {
    if (abs(hp[i] - hp[i + 1]) < tol) {
      z[i] <- (x[i] + x[i + 1]) / 2
    } else {
      z[i] <- (h[i + 1] - h[i] - x[i + 1] * hp[i + 1] + x[i] * hp[i]) / (hp[i] - hp[i + 1])
    }
  }
  if (any(diff(z) <= 0) || any(z <= x[-k]) || any(z >= x[-1])) {
    stop("Failed to construct a valid upper hull (intersection points out of order); ",
         "the density does not appear to be log-concave.", call. = FALSE)
  }

  z_full <- c(lower, z, upper)
  u_left  <- h + hp * (z_full[-(k + 1)] - x)  # tangent line i, evaluated at its left edge
  u_right <- h + hp * (z_full[-1] - x)        # tangent line i, evaluated at its right edge

  logw <- numeric(k)
  for (i in seq_len(k)) {
    m <- hp[i]
    ul <- u_left[i]; ur <- u_right[i]
    if (i == 1L && !is.finite(z_full[1])) {
      logw[i] <- ur - log(m)          # left tail, requires m > 0
    } else if (i == k && !is.finite(z_full[k + 1])) {
      logw[i] <- ul - log(-m)         # right tail, requires m < 0
    } else if (abs(m) < tol) {
      logw[i] <- ul + log(z_full[i + 1] - z_full[i])
    } else {
      hi <- max(ul, ur); lo <- min(ul, ur)
      logw[i] <- hi + log1p(-exp(lo - hi)) - log(abs(m))
    }
  }

  logw_max <- max(logw)
  w <- exp(logw - logw_max)
  cum_prob <- cumsum(w) / sum(w)

  list(x = x, h = h, hp = hp, z = z_full, u_left = u_left, u_right = u_right,
       logw = logw, cum_prob = cum_prob)
}

.ars_upper_hull_value <- function(hull, x_star, segment) {
  i <- segment
  hull$h[i] + hull$hp[i] * (x_star - hull$x[i])
}

.ars_lower_hull_value <- function(hull, x_star) {
  x <- hull$x; h <- hull$h
  k <- length(x)
  if (x_star <= x[1] || x_star >= x[k]) return(-Inf)
  j <- findInterval(x_star, x)
  h[j] + (h[j + 1] - h[j]) * (x_star - x[j]) / (x[j + 1] - x[j])
}

## ------------------------------------------------------------------------
## 6. Sampling from the piecewise-exponential upper hull
## ------------------------------------------------------------------------

.ars_sample_upper_hull <- function(hull) {
  k <- length(hull$x)
  u1 <- runif(1)
  idx <- which(u1 <= hull$cum_prob)[1]
  if (is.na(idx)) idx <- k

  u2 <- runif(1)
  m <- hull$hp[idx]
  zl <- hull$z[idx]; zr <- hull$z[idx + 1]

  if (idx == 1L && !is.finite(zl)) {
    x_star <- zr + log(u2) / m
  } else if (idx == k && !is.finite(zr)) {
    x_star <- zl + log(u2) / m
  } else if (abs(m) < 1e-8) {
    x_star <- zl + u2 * (zr - zl)
  } else {
    x_star <- zl + log1p(u2 * expm1(m * (zr - zl))) / m
  }

  list(x = x_star, segment = idx)
}

## ------------------------------------------------------------------------
## 7. Main driver
## ------------------------------------------------------------------------

#' Adaptive rejection sampling from a log-concave density
#'
#' @param f density function, vectorized, e.g. dnorm, dexp (need not be normalized)
#' @param n number of samples to draw (positive integer)
#' @param lower,upper support of the density (may be -Inf/Inf)
#' @param x_init optional numeric vector (length >= 2) of initial abscissae
#' @param ... additional arguments passed on to f (e.g. rate = 2)
#' @param max_points cap on the number of abscissae used to build the hull
#' @param max_iter safety cap on total proposal/accept-reject iterations
#' @param step relative step size used for numerical differentiation of log(f)
#' @param tol numerical tolerance used inside hull construction
#' @param concavity_tol relative tolerance for the log-concavity check
#' @return numeric vector of length n, with attributes "n_evaluations",
#'   "n_abscissae" and "n_iterations" giving diagnostic information.
ars <- function(f, n, lower = -Inf, upper = Inf, x_init = NULL, ...,
                 max_points = 200L, max_iter = 200000L, step = 1e-5,
                 tol = 1e-8, concavity_tol = 1e-4) {

  .ars_validate_inputs(f, n, lower, upper, x_init)
  n <- as.integer(round(n))

  init <- .ars_initialize_abscissae(f, lower, upper, x_init, step, ...)
  hull <- .ars_build_hull(init$x, init$h, init$hp, lower, upper, tol, concavity_tol)

  samples <- numeric(n)
  n_accepted <- 0L
  n_eval <- 0L
  iter <- 0L

  while (n_accepted < n) {
    iter <- iter + 1L
    if (iter > max_iter) {
      stop(sprintf("Exceeded max_iter = %d iterations while sampling (accepted %d / %d draws). ",
                    max_iter, n_accepted, n), call. = FALSE)
    }

    draw <- .ars_sample_upper_hull(hull)
    x_star <- draw$x
    seg <- draw$segment
    w <- runif(1)

    u_val <- .ars_upper_hull_value(hull, x_star, seg)
    l_val <- .ars_lower_hull_value(hull, x_star)

    if (is.finite(l_val) && w <= exp(l_val - u_val)) {
      # squeeze test passed: accept without evaluating f
      n_accepted <- n_accepted + 1L
      samples[n_accepted] <- x_star
    } else {
      h_star <- .ars_log_density(f, x_star, ...)
      n_eval <- n_eval + 1L
      if (w <= exp(h_star - u_val)) {
        n_accepted <- n_accepted + 1L
        samples[n_accepted] <- x_star
      }
      if (length(hull$x) < max_points) {
        hp_star <- .ars_log_density_deriv(f, x_star, lower, upper, step, ...)
        new_x <- c(hull$x, x_star)
        new_h <- c(hull$h, h_star)
        new_hp <- c(hull$hp, hp_star)
        ord <- order(new_x)
        hull <- .ars_build_hull(new_x[ord], new_h[ord], new_hp[ord], lower, upper, tol, concavity_tol)
      }
    }
  }

  attr(samples, "n_evaluations") <- n_eval
  attr(samples, "n_abscissae") <- length(hull$x)
  attr(samples, "n_iterations") <- iter
  samples
}

## ------------------------------------------------------------------------
## 8. Formal tests
## ------------------------------------------------------------------------

#' Run a battery of formal tests comparing ars() output to known distributions
#'
#' Prints "NAME: PASS" / "NAME: FAIL" plus summary statistics for each test,
#' then writes sample files to /app/normal_samples.txt and
#' /app/exponential_samples.txt.
test <- function(n = 3000, seed = 20260813, verbose = TRUE) {

  set.seed(seed)
  results <- list()

  run_test <- function(name, fn) {
    res <- tryCatch(fn(), error = function(e) list(pass = FALSE, message = conditionMessage(e)))
    results[[name]] <<- res
    status <- if (isTRUE(res$pass)) "PASS" else "FAIL"
    cat(sprintf("%s: %s\n", name, status))
    if (!is.null(res$mean) && !is.na(res$mean)) {
      cat(sprintf("  mean = %.4f, sd = %.4f\n", res$mean, res$sd))
    }
    if (!is.null(res$message)) cat(sprintf("  %s\n", res$message))
    cat("\n")
  }

  cat("==========================================================\n")
  cat("Adaptive Rejection Sampling -- formal test suite\n")
  cat(sprintf("(n = %d samples per distributional test, seed = %d)\n", n, seed))
  cat("==========================================================\n\n")

  ## -- Test 1: standard normal -------------------------------------------
  run_test("NORMAL_DENSITY", function() {
    s <- ars(dnorm, n = n)
    m <- mean(s); sdv <- sd(s)
    ks <- ks.test(s, "pnorm")
    pass <- ks$p.value > 0.01 && abs(m) < 4 / sqrt(n) && abs(sdv - 1) < 0.15
    list(pass = pass, mean = m, sd = sdv,
         message = sprintf("KS test vs N(0,1): D = %.4f, p = %.4f (target mean 0, sd 1)",
                            ks$statistic, ks$p.value))
  })

  ## -- Test 2: exponential -------------------------------------------------
  run_test("EXPONENTIAL_DENSITY", function() {
    s <- ars(dexp, n = n, lower = 0, upper = Inf, x_init = c(0.2, 1.5))
    m <- mean(s); sdv <- sd(s)
    ks <- ks.test(s, "pexp")
    pass <- ks$p.value > 0.01 && abs(m - 1) < 0.2 && abs(sdv - 1) < 0.2
    list(pass = pass, mean = m, sd = sdv,
         message = sprintf("KS test vs Exp(1): D = %.4f, p = %.4f (target mean 1, sd 1)",
                            ks$statistic, ks$p.value))
  })

  ## -- Test 3: gamma(shape = 3, rate = 2) ----------------------------------
  run_test("GAMMA_DENSITY", function() {
    s <- ars(function(x) dgamma(x, shape = 3, rate = 2), n = n, lower = 0, upper = Inf,
              x_init = c(0.5, 2.5))
    m <- mean(s); sdv <- sd(s)
    true_mean <- 3 / 2; true_sd <- sqrt(3) / 2
    ks <- ks.test(s, "pgamma", shape = 3, rate = 2)
    pass <- ks$p.value > 0.01 && abs(m - true_mean) < 0.2 && abs(sdv - true_sd) < 0.2
    list(pass = pass, mean = m, sd = sdv,
         message = sprintf("KS test vs Gamma(3,2): D = %.4f, p = %.4f (target mean %.4f, sd %.4f)",
                            ks$statistic, ks$p.value, true_mean, true_sd))
  })

  ## -- Test 4: truncated normal on a bounded domain ------------------------
  run_test("TRUNCATED_NORMAL_DENSITY", function() {
    a <- -2; b <- 2
    s <- ars(dnorm, n = n, lower = a, upper = b)
    Z <- pnorm(b) - pnorm(a)
    true_mean <- (dnorm(a) - dnorm(b)) / Z
    true_var <- 1 + (a * dnorm(a) - b * dnorm(b)) / Z - true_mean^2
    m <- mean(s); sdv <- sd(s)
    pass <- all(s > a) && all(s < b) && abs(m - true_mean) < 0.1 && abs(sdv - sqrt(true_var)) < 0.1
    list(pass = pass, mean = m, sd = sdv,
         message = sprintf("N(0,1) truncated to [%.0f, %.0f]: target mean %.4f, sd %.4f; all samples within bounds: %s",
                            a, b, true_mean, sqrt(true_var), all(s > a) && all(s < b)))
  })

  ## -- Test 5: non-log-concave density is detected and rejected ------------
  run_test("LOG_CONCAVITY_CHECK", function() {
    bimodal <- function(x) 0.5 * dnorm(x, -4, 1) + 0.5 * dnorm(x, 4, 1)
    caught <- tryCatch({
      ars(bimodal, n = 20, x_init = c(-2, 2))
      NULL
    }, error = function(e) conditionMessage(e))
    pass <- !is.null(caught) && grepl("concave", caught, ignore.case = TRUE)
    list(pass = pass, mean = NA, sd = NA,
         message = if (pass) paste("Correctly rejected non-log-concave density:", caught)
                   else "Failed to detect a non-log-concave (bimodal) density")
  })

  ## -- Test 6: input validation --------------------------------------------
  run_test("INPUT_VALIDATION", function() {
    is_err <- function(expr) inherits(tryCatch(expr, error = function(e) e), "error")
    checks <- c(
      neg_n      = is_err(ars(dnorm, -5)),
      zero_n     = is_err(ars(dnorm, 0)),
      noninteger = is_err(ars(dnorm, 10.5)),
      not_a_fn   = is_err(ars("not_a_function", 10)),
      bad_domain = is_err(ars(dnorm, 10, lower = 5, upper = 1)),
      bad_xinit  = is_err(ars(dnorm, 10, x_init = c(100, 200)))
    )
    pass <- all(checks)
    list(pass = pass, mean = NA, sd = NA,
         message = sprintf("%d/%d invalid-input cases correctly raised an error (%s)",
                            sum(checks), length(checks),
                            paste(names(checks)[!checks], collapse = ", ")))
  })

  ## -- Summary --------------------------------------------------------------
  n_pass <- sum(vapply(results, function(r) isTRUE(r$pass), logical(1)))
  n_total <- length(results)
  cat("==========================================================\n")
  cat(sprintf("SUMMARY: %d / %d tests passed\n", n_pass, n_total))
  cat("==========================================================\n\n")

  ## -- Write sample files as evidence of correct sampling -------------------
  normal_samples <- ars(dnorm, n = 2000)
  exp_samples <- ars(dexp, n = 2000, lower = 0, upper = Inf, x_init = c(0.2, 1.5))
  writeLines(format(normal_samples, digits = 10), "/app/normal_samples.txt")
  writeLines(format(exp_samples, digits = 10), "/app/exponential_samples.txt")
  cat("Wrote /app/normal_samples.txt and /app/exponential_samples.txt\n")

  invisible(results)
}

if (sys.nframe() == 0L) {
  test()
}

