## ------------------------------------------------------------------------
## 2. Density evaluation (log scale) and numerical derivative
## ------------------------------------------------------------------------

.ars_log_density <- function(f, x, ...) {
  fx <- f(x, ...)
  if (!is.numeric(fx) || length(fx) != length(x)) {
    stop("The density function must return a numeric vector of the same length as its input (vectorized).", call. = FALSE)
  }
  if (anyNA(fx)) {
    stop("The supplied density function returned NA for some input value(s); check the function and domain.", call. = FALSE)
  }
