  delta <- pmax(step * pmax(abs(x), 1), 1e-8)
  eps_bound <- 1e-10
  xu <- pmin(x + delta, upper - eps_bound)
  xl <- pmax(x - delta, lower + eps_bound)
  hu <- .ars_log_density(f, xu, ...)
  hl <- .ars_log_density(f, xl, ...)
  (hu - hl) / (xu - xl)
}

## ------------------------------------------------------------------------
## 3. Log-concavity check
## ------------------------------------------------------------------------

